$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((git rev-parse --show-toplevel).Trim());$zip=Get-ChildItem -LiteralPath $HOME\Downloads -Filter 'CPF_DOCUMENTATION_V1_2_5_FINAL_OVERLAY_*.zip'|Sort-Object LastWriteTime -Descending|Select-Object -First 1;if(!$zip){throw 'OVERLAY ZIP NOT FOUND'};$tmp=Join-Path $env:TEMP ('cpf-doc-del-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory $tmp|Out-Null;try{Expand-Archive -LiteralPath $zip.FullName -DestinationPath $tmp -Force;$m=Join-Path $tmp 'cpf-docs\deliverables\documentation\DELETE_MANIFEST.txt';Get-Content -LiteralPath $m|ForEach-Object{$s=$_.Trim();if($s-and-not$s.StartsWith('#')){if([IO.Path]::IsPathRooted($s)-or$s.Contains('..')-or[Management.Automation.WildcardPattern]::ContainsWildcardCharacters($s)){throw "UNSAFE DELETE PATH: $s"};$p=[IO.Path]::GetFullPath((Join-Path $root $s.Replace('/','\')));if(!$p.StartsWith($root.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){throw "OUTSIDE ROOT: $s => $p"};if(Test-Path -LiteralPath $p){$i=Get-Item -LiteralPath $p -Force;if($i.PSIsContainer){throw "FILE MANIFEST CONTAINS DIRECTORY: $s"};Remove-Item -LiteralPath $p -Force}}};Write-Host '[CPF][DOC] DOCUMENTATION GARBAGE DELETE PASS'}finally{Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue}